from decimal import Decimal, ROUND_HALF_EVEN

def conciliar_lote_pse(transacciones_internas, archivo_ach):
    indice_ach = {}
    for ach in archivo_ach:
        clave = (ach['referencia'], Decimal(str(ach['monto'])).quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN))
        indice_ach[clave] = ach

    conciliadas, discrepancias = [], []
    for tx in transacciones_internas:
        if tx.get('estado') == 'PENDIENTE':
            continue
        clave = (tx['referencia'], Decimal(str(tx['monto'])).quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN))
        if clave in indice_ach:
            conciliadas.append(tx['id'])
        else:
            discrepancias.append(tx['id'])

    return {'conciliadas': conciliadas, 'discrepancias': discrepancias}
